import{_ as e,c as n,o,j as r,Y as d,t as i}from"./chunks/framework.D-NV0Bun.js";const f=JSON.parse('{"title":"ls | x-cmd man (man1) | list directory contents","titleTemplate":false,"description":"x-cmd man (man1 Manual Page) | ls - list directory contents","frontmatter":{"pageClass":"x-man","head":[["meta",{"name":"og:title","content":"ls | x-cmd man (man1) | list directory contents"}],["meta",{"name":"og:description","content":"x-cmd man (man1 Manual Page) | ls - list directory contents"}]]},"headers":[],"params":{"isMan":true,"man":"ls","category":"man1","desc":"list directory contents"},"relativePath":"man1/ls.md","filePath":"man1/[man].md"}'),a={name:"man1/ls.md"},l={class:"visually-hidden"};function g(s,t,h,c,p,m){return o(),n("div",null,[r("h1",l,i(s.$params.man),1),t[0]||(t[0]=d(`<h2 id="name" tabindex="-1">NAME <a class="header-anchor" href="#name" aria-label="Permalink to &quot;NAME&quot;">​</a></h2><p>ls - list directory contents</p><h2 id="synopsis" tabindex="-1">SYNOPSIS <a class="header-anchor" href="#synopsis" aria-label="Permalink to &quot;SYNOPSIS&quot;">​</a></h2><p><strong>ls</strong> [<em>OPTION</em>]... [<em>FILE</em>]...</p><h2 id="description" tabindex="-1">DESCRIPTION <a class="header-anchor" href="#description" aria-label="Permalink to &quot;DESCRIPTION&quot;">​</a></h2><p>List information about the FILEs (the current directory by default). Sort entries alphabetically if none of <strong>-cftuvSUX</strong> nor <strong>--sort</strong> is specified.</p><p>Mandatory arguments to long options are mandatory for short options too.</p><dl><dt><strong>-a</strong>, <strong>--all</strong></dt><dd>do not ignore entries starting with .</dd><dt><strong>-A</strong>, <strong>--almost-all</strong></dt><dd>do not list implied . and ..</dd><dt><strong>--author</strong></dt><dd>with <strong>-l</strong>, print the author of each file</dd><dt><strong>-b</strong>, <strong>--escape</strong></dt><dd>print C-style escapes for nongraphic characters</dd><dt><strong>--block-size</strong>=<em>SIZE</em></dt><dd>with <strong>-l</strong>, scale sizes by SIZE when printing them; e.g., &#39;--block-size=M&#39;; see SIZE format below</dd><dt><strong>-B</strong>, <strong>--ignore-backups</strong></dt><dd>do not list implied entries ending with ~</dd><dt><strong>-c</strong></dt><dd>with <strong>-lt</strong>: sort by, and show, ctime (time of last change of file status information); with <strong>-l</strong>: show ctime and sort by name; otherwise: sort by ctime, newest first</dd><dt><strong>-C</strong></dt><dd>list entries by columns</dd><dt><strong>--color</strong>[=<em>WHEN</em>]</dt><dd>color the output WHEN; more info below</dd><dt><strong>-d</strong>, <strong>--directory</strong></dt><dd>list directories themselves, not their contents</dd><dt><strong>-D</strong>, <strong>--dired</strong></dt><dd>generate output designed for Emacs&#39; dired mode</dd><dt><strong>-f</strong></dt><dd>list all entries in directory order</dd><dt><strong>-F</strong>, <strong>--classify</strong>[=<em>WHEN</em>]</dt><dd>append indicator (one of */=&gt;@|) to entries WHEN</dd><dt><strong>--file-type</strong></dt><dd>likewise, except do not append &#39;*&#39;</dd><dt><strong>--format</strong>=<em>WORD</em></dt><dd>across <strong>-x</strong>, commas <strong>-m</strong>, horizontal <strong>-x</strong>, long <strong>-l</strong>, single-column <strong>-1</strong>, verbose <strong>-l</strong>, vertical <strong>-C</strong></dd><dt><strong>--full-time</strong></dt><dd>like <strong>-l</strong> <strong>--time-style</strong>=<em>full-iso</em></dd><dt><strong>-g</strong></dt><dd>like <strong>-l</strong>, but do not list owner</dd><dt><strong>--group-directories-first</strong></dt><dd>group directories before files; can be augmented with a <strong>--sort</strong> option, but any use of <strong>--sort</strong>=<em>none</em> (<strong>-U</strong>) disables grouping</dd><dt><strong>-G</strong>, <strong>--no-group</strong></dt><dd>in a long listing, don&#39;t print group names</dd><dt><strong>-h</strong>, <strong>--human-readable</strong></dt><dd>with <strong>-l</strong> and <strong>-s</strong>, print sizes like 1K 234M 2G etc.</dd><dt><strong>--si</strong></dt><dd>likewise, but use powers of 1000 not 1024</dd><dt><strong>-H</strong>, <strong>--dereference-command-line</strong></dt><dd>follow symbolic links listed on the command line</dd><dt><strong>--dereference-command-line-symlink-to-dir</strong></dt><dd>follow each command line symbolic link that points to a directory</dd><dt><strong>--hide</strong>=<em>PATTERN</em></dt><dd>do not list implied entries matching shell PATTERN (overridden by <strong>-a</strong> or <strong>-A</strong>)</dd><dt><strong>--hyperlink</strong>[=<em>WHEN</em>]</dt><dd>hyperlink file names WHEN</dd><dt><strong>--indicator-style</strong>=<em>WORD</em></dt><dd>append indicator with style WORD to entry names: none (default), slash (<strong>-p</strong>), file-type (<strong>--file-type</strong>), classify (<strong>-F</strong>)</dd><dt><strong>-i</strong>, <strong>--inode</strong></dt><dd>print the index number of each file</dd><dt><strong>-I</strong>, <strong>--ignore</strong>=<em>PATTERN</em></dt><dd>do not list implied entries matching shell PATTERN</dd><dt><strong>-k</strong>, <strong>--kibibytes</strong></dt><dd>default to 1024-byte blocks for file system usage; used only with <strong>-s</strong> and per directory totals</dd><dt><strong>-l</strong></dt><dd>use a long listing format</dd><dt><strong>-L</strong>, <strong>--dereference</strong></dt><dd>when showing file information for a symbolic link, show information for the file the link references rather than for the link itself</dd><dt><strong>-m</strong></dt><dd>fill width with a comma separated list of entries</dd><dt><strong>-n</strong>, <strong>--numeric-uid-gid</strong></dt><dd>like <strong>-l</strong>, but list numeric user and group IDs</dd><dt><strong>-N</strong>, <strong>--literal</strong></dt><dd>print entry names without quoting</dd><dt><strong>-o</strong></dt><dd>like <strong>-l</strong>, but do not list group information</dd><dt><strong>-p</strong>, <strong>--indicator-style</strong>=<em>slash</em></dt><dd>append / indicator to directories</dd><dt><strong>-q</strong>, <strong>--hide-control-chars</strong></dt><dd>print ? instead of nongraphic characters</dd><dt><strong>--show-control-chars</strong></dt><dd>show nongraphic characters as-is (the default, unless program is &#39;ls&#39; and output is a terminal)</dd><dt><strong>-Q</strong>, <strong>--quote-name</strong></dt><dd>enclose entry names in double quotes</dd><dt><strong>--quoting-style</strong>=<em>WORD</em></dt><dd>use quoting style WORD for entry names: literal, locale, shell, shell-always, shell-escape, shell-escape-always, c, escape (overrides QUOTING_STYLE environment variable)</dd><dt><strong>-r</strong>, <strong>--reverse</strong></dt><dd>reverse order while sorting</dd><dt><strong>-R</strong>, <strong>--recursive</strong></dt><dd>list subdirectories recursively</dd><dt><strong>-s</strong>, <strong>--size</strong></dt><dd>print the allocated size of each file, in blocks</dd><dt><strong>-S</strong></dt><dd>sort by file size, largest first</dd><dt><strong>--sort</strong>=<em>WORD</em></dt><dd>sort by WORD instead of name: none (<strong>-U</strong>), size (<strong>-S</strong>), time (<strong>-t</strong>), version (<strong>-v</strong>), extension (<strong>-X</strong>), width</dd><dt><strong>--time</strong>=<em>WORD</em></dt><dd>select which timestamp used to display or sort; access time (<strong>-u</strong>): atime, access, use; metadata change time (<strong>-c</strong>): ctime, status; modified time (default): mtime, modification; birth time: birth, creation;</dd></dl><div class="language-sh vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sh</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">with</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> **</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">-l</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">**</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> WORD</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> determines</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> which</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> time</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> to</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> show</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">; </span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">with</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">**</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">\\-</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">-sort</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">**</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">=</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">time</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, sort by WORD (</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">newest</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> first</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><dl><dt><strong>--time-style</strong>=<em>TIME_STYLE</em></dt><dd>time/date format with <strong>-l</strong>; see TIME_STYLE below</dd><dt><strong>-t</strong></dt><dd>sort by time, newest first; see <strong>--time</strong></dd><dt><strong>-T</strong>, <strong>--tabsize</strong>=<em>COLS</em></dt><dd>assume tab stops at each COLS instead of 8</dd><dt><strong>-u</strong></dt><dd>with <strong>-lt</strong>: sort by, and show, access time; with <strong>-l</strong>: show access time and sort by name; otherwise: sort by access time, newest first</dd><dt><strong>-U</strong></dt><dd>do not sort; list entries in directory order</dd><dt><strong>-v</strong></dt><dd>natural sort of (version) numbers within text</dd><dt><strong>-w</strong>, <strong>--width</strong>=<em>COLS</em></dt><dd>set output width to COLS. 0 means no limit</dd><dt><strong>-x</strong></dt><dd>list entries by lines instead of by columns</dd><dt><strong>-X</strong></dt><dd>sort alphabetically by entry extension</dd><dt><strong>-Z</strong>, <strong>--context</strong></dt><dd>print any security context of each file</dd><dt><strong>--zero</strong></dt><dd>end each output line with NUL, not newline</dd><dt><strong>-1</strong></dt><dd>list one file per line</dd><dt><strong>--help</strong></dt><dd>display this help and exit</dd><dt><strong>--version</strong></dt><dd>output version information and exit</dd></dl><p>The SIZE argument is an integer and optional unit (example: 10K is 10*1024). Units are K,M,G,T,P,E,Z,Y,R,Q (powers of 1024) or KB,MB,... (powers of 1000). Binary prefixes can be used, too: KiB=K, MiB=M, and so on.</p><p>The TIME_STYLE argument can be full-iso, long-iso, iso, locale, or +FORMAT. FORMAT is interpreted like in <strong>date</strong>(1). If FORMAT is FORMAT1&lt;newline&gt;FORMAT2, then FORMAT1 applies to non-recent files and FORMAT2 to recent files. TIME_STYLE prefixed with &#39;posix-&#39; takes effect only outside the POSIX locale. Also the TIME_STYLE environment variable sets the default style to use.</p><p>The WHEN argument defaults to &#39;always&#39; and can also be &#39;auto&#39; or &#39;never&#39;.</p><p>Using color to distinguish file types is disabled both by default and with <strong>--color</strong>=<em>never</em>. With <strong>--color</strong>=<em>auto</em>, ls emits color codes only when standard output is connected to a terminal. The LS_COLORS environment variable can change the settings. Use the <strong>dircolors</strong>(1) command to set it.</p><h3 id="exit-status" tabindex="-1">Exit status: <a class="header-anchor" href="#exit-status" aria-label="Permalink to &quot;Exit status:&quot;">​</a></h3><dl><dt>0</dt><dd>if OK,</dd><dt>1</dt><dd>if minor problems (e.g., cannot access subdirectory),</dd><dt>2</dt><dd>if serious trouble (e.g., cannot access command-line argument).</dd></dl><h2 id="author" tabindex="-1">AUTHOR <a class="header-anchor" href="#author" aria-label="Permalink to &quot;AUTHOR&quot;">​</a></h2><p>Written by Richard M. Stallman and David MacKenzie.</p><h2 id="reporting-bugs" tabindex="-1">REPORTING BUGS <a class="header-anchor" href="#reporting-bugs" aria-label="Permalink to &quot;REPORTING BUGS&quot;">​</a></h2><p>GNU coreutils online help: &lt;<a href="https://www.gnu.org/software/coreutils/%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/\\</a>&gt; <br> Report any translation bugs to &lt;<a href="https://translationproject.org/team/%5C" target="_blank" rel="noreferrer">https://translationproject.org/team/\\</a>&gt;</p><h2 id="copyright" tabindex="-1">COPYRIGHT <a class="header-anchor" href="#copyright" aria-label="Permalink to &quot;COPYRIGHT&quot;">​</a></h2><p>Copyright © 2023 Free Software Foundation, Inc. License GPLv3+: GNU GPL version 3 or later &lt;<a href="https://gnu.org/licenses/gpl.html%5C" target="_blank" rel="noreferrer">https://gnu.org/licenses/gpl.html\\</a>&gt;. <br> This is free software: you are free to change and redistribute it. There is NO WARRANTY, to the extent permitted by law.</p><h2 id="see-also" tabindex="-1">SEE ALSO <a class="header-anchor" href="#see-also" aria-label="Permalink to &quot;SEE ALSO&quot;">​</a></h2><p><strong>dircolors</strong>(1)</p><p><br> Full documentation &lt;<a href="https://www.gnu.org/software/coreutils/ls%5C" target="_blank" rel="noreferrer">https://www.gnu.org/software/coreutils/ls\\</a>&gt; <br> or available locally via: info &#39;(coreutils) ls invocation&#39;</p>`,25))])}const y=e(a,[["render",g]]);export{f as __pageData,y as default};
